import{_ as l,o as t,c as a,a5 as i}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"写作课作业-068","description":"","frontmatter":{"date":"2020-09-26T21:02:54","title":"写作课作业-068","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"思考","slug":"思考","link":"#思考","children":[]}],"relativePath":"posts/homework/068.md","filePath":"posts/homework/068.md"}'),o={name:"posts/homework/068.md"};function r(s,e,n,p,c,_){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>9.25 写作作业：读《微信互联网平民创业》之《1. 你把微信当作什么？》，读书笔记的模板（可以在此基础上，资源发挥）：</p><ol><li>总结书中知识要点：</li><li>我对知识点的思考：</li><li>书中精彩的例子，可以用在其他什么地方：</li><li>书中用了排比、递进、转折了吗？</li><li>哪些知识点可以运用到自己学习、生活和工作中。</li></ol></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>对绝大多数人来说，微信一直以来仅仅是一个「熟人之间使用的即时通讯工具」。</li><li>微信借助 腾讯的用户基础，允许用户使用 QQ 号码和电话号码注册(并同时允许用户上传通讯 录)，几乎是转瞬间就获得了大量用户，随后用各式各样的手段(附近的人、漂流瓶等 等)没怎么费劲就直接灭掉了国内所有其它同类产品。</li><li>在微信上，你所能做的，不再仅仅是把它当作一个替代运营商所提供的短信功能 的免费替代品而已了。你当然能用它向熟人发消息，不仅可以用文字，还可以包括图片、音频或视频，甚至发送很⻓的文章，你也可以把文章发表在微信公共账号或者互联 网上的任何地方之后给对方发送一个链接;你能用它群发消息 —— 发到某个或者多个群 里，或者只是静静地发布在朋友圈，人家爱看不看;你还能用它给很多陌生人发消息， 比如用之前就有的微信公共账号或者现在刚有的微信视频号......更为重要的是，在微信上，与交易有关的每一个环节都可以完成，并且「无缝衔接」。 广告发布、产品宣发、售前咨询、支付、售后服务...... 闭环。</li><li>微信干脆是个完整的互联网，整个互联网几乎全都要搬到微信上了。</li></ul><h2 id="思考" tabindex="-1">思考 <a class="header-anchor" href="#思考" aria-label="Permalink to &quot;思考&quot;">​</a></h2><p>2015年因为换工作，开始使用微信，那个时候还有不少QQ群组，需要在不同的聊天工具间切换，然后微信很多消息都是语音的，就觉得增加了自己是个麻烦。之后越来越多的人用微信，微信也有了桌面版，有了语音转文字，QQ消息越来越少，慢慢的工作的交流对切换到了微信上，后来公司也有公众号的业务，支付也更方便起来，这才慢慢习惯微信。如果11年发布微信，15年，其他微信已然不是新事物，但自己对于新事物还是缺少了好奇心。</p><p>在《梁宁·产品思维30讲》中有一讲说“系统世界观：微信、米聊、陌陌”，其中就说到微信和米聊，除了系统能力比小米强，更重要的分水岭就是微信开启了陌生人社交，而米聊没有。而在《一往无前》中说，一家公司不可能在创业初期什么都想要，如果对想要，往往最好什么也得不到。另外也因为米聊负责人崔宝秋是“阳光交友”的坚定者，对陌生人社交过不了他的心理关。微信对米聊来说是新的，小米对腾讯来说是新的，而腾讯因为有QQ，有Foxmail的很多积累，让微信有机会赢，对于一个人来说，成长也不断受到自身能力和积累的影响，也要不断的打开自己的认知，不断的积累。</p><p>之前是CopyFromUSA，现在是Copy2USA。始终保持是一个学习者，学多了会成为领先。</p>',7)])])}const m=l(o,[["render",r]]);export{h as __pageData,m as default};
